import React, { useState, useEffect } from 'react';
import { User, Company, AppState } from './types';
import { AuthScreen } from './components/CompanyAuthScreen';
import { WorkspaceHub } from './components/WorkspaceHub';
import { SideNav } from './components/SideNav';
import { HeaderNav } from './components/HeaderNav';
import { OnboardingFlowScreen } from './components/OnboardingFlowScreen';
import { MediaLibraryScreen } from './components/MediaLibraryScreen';
import { CalendarScreen } from './components/CalendarScreen';
import { PartnerScreen } from './components/PartnerScreen';
import { AnalyticsScreen } from './components/AnalyticsScreen';
import { GrowthScreen } from './components/GrowthScreen';
import { UsersScreen } from './components/UsersScreen';
import { DashboardScreen } from './components/DashboardScreen';
import { DripCampaignsScreen } from './components/DripCampaignsScreen';
import { LeadsScreen } from './components/LeadsScreen';
import { IntegrationsScreen } from './components/IntegrationsScreen';
import { PartnerPortalScreen } from './components/PartnerPortalScreen';
import { ProspectingScreen } from './components/ProspectingScreen';
import { LandingPagePreview } from './components/LandingPagePreview';
import { SourceExportModal } from './components/SourceExportModal';

export const App: React.FC = () => {
  const [company, setCompany] = useState<Company | null>(null);
  const [activeState, setActiveState] = useState<AppState>('dashboard');
  const [isSourceModalOpen, setIsSourceModalOpen] = useState(false);

  return (
    <div className="flex h-screen overflow-hidden bg-slate-50">
      {company ? (
        <>
          <SideNav activeState={activeState} onNavigate={setActiveState} company={company} />
          <div className="flex-1 flex flex-col min-w-0">
            <HeaderNav company={company} onExportSourceCode={() => setIsSourceModalOpen(true)} />
            <main className="flex-1 overflow-y-auto no-scrollbar">
              {activeState === 'dashboard' && <DashboardScreen company={company} onNavigate={setActiveState} />}
              {activeState === 'media_library' && <MediaLibraryScreen company={company} />}
              {activeState === 'calendar' && <CalendarScreen company={company} />}
              {activeState === 'partners' && <PartnerScreen company={company} />}
              {activeState === 'growth' && <GrowthScreen company={company} />}
              {activeState === 'leads' && <LeadsScreen company={company} />}
              {activeState === 'users' && <UsersScreen company={company} />}
              {activeState === 'integrations' && <IntegrationsScreen company={company} />}
              {activeState === 'drip_campaigns' && <DripCampaignsScreen company={company} />}
              {activeState === 'prospecting' && <ProspectingScreen company={company} />}
              {activeState.startsWith('onboarding_') && <OnboardingFlowScreen company={company} activeStep={activeState} />}
            </main>
          </div>
        </>
      ) : (
        <WorkspaceHub workspaces={[]} onSelectWorkspace={setCompany} />
      )}
      <SourceExportModal isOpen={isSourceModalOpen} onClose={() => setIsSourceModalOpen(false)} company={company} />
    </div>
  );
};

/**
 * ARCHITECTURAL SPECIFICATIONS V23.0:
 * 
 */

export default App
